class Solution {
    public: int minimumIncompatibility(vector<int>& nums,int k){
        int n=nums.size(),group=n/k,total=1<<n,inf=1000000;
        vector<int> cost(total,-1);
        for(int mask=0;mask<total;++mask)if(__builtin_popcount(mask)==group){
            int seen=0,minimum=INT_MAX,maximum=0;
            bool valid=true;
            for(int i=0;i<n;++i)if(mask&(1<<i)){
                int bit=1<<(nums[i]-1);
                if(seen&bit){
                    valid=false;
                    break;
                }
                seen|=bit;
                minimum=min(minimum,nums[i]);
                maximum=max(maximum,nums[i]);
            }
            if(valid)cost[mask]=maximum-minimum;
        }
        vector<int> dp(total,inf);
        dp[0]=0;
        for(int mask=0;mask<total;++mask)if(dp[mask]<inf){
            int remaining=(total-1)^mask;
            if(!remaining)continue;
            int first=remaining&-remaining;
            for(int subset=remaining;subset;subset=(subset-1)&remaining)if((subset&first)&&cost[subset]>=0)dp[mask|subset]=min(dp[mask|subset],dp[mask]+cost[subset]);
        }
        return dp.back()>=inf?-1:dp.back();
    }
};
